"""Read only responses generated by the user's normal search page."""
import asyncio
import json
import math
import re
from dataclasses import dataclass
from urllib.parse import parse_qs, urlsplit

SEARCH_API = '/h5/mtop.taobao.idlemtopsearch.pc.search/1.0/'


@dataclass
class SearchPayload:
    cards: list
    failure: str = ''


def parse_search_payload(payload):
    """Unknown schemas fail closed; an API error is never an empty search."""
    if not isinstance(payload, dict):
        return SearchPayload([], 'parse_failed')
    ret = payload.get('ret', [])
    if not isinstance(ret, list):
        return SearchPayload([], 'parse_failed')
    codes = ' '.join(str(value) for value in ret)
    if 'FAIL_SYS_USER_VALIDATE' in codes:
        return SearchPayload([], 'verification_required')
    if any(code in codes for code in ('SESSION_EXPIRED', 'TOKEN_EXPIRED', 'TOKEN_EMPTY', 'USER_NOT_LOGIN')):
        return SearchPayload([], 'login_required')
    if not any(str(code).startswith('SUCCESS::') for code in ret):
        return SearchPayload([], 'service_busy' if any(k in codes for k in ('TRAFFIC', 'LIMIT', 'BUSY')) else 'parse_failed')
    data = payload.get('data')
    rows = data.get('resultList') if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return SearchPayload([], 'parse_failed')
    cards = []
    for row in rows:
        try:
            main = row['data']['item']['main']
            item = main['exContent']
            key, title = str(item['itemId']), item['title']
            parts = item['price']
            raw = ''.join(str(part.get('text', '')) for part in parts if isinstance(part, dict))
            match = re.fullmatch(r'(?:当前价)?\s*[¥￥]?\s*(\d+(?:\.\d+)?)\s*(万)?', raw)
            if not key.isdigit() or not isinstance(title, str) or not title.strip() or not match:
                continue
            price = float(match[1]) * (10000 if match[2] else 1)
            if not math.isfinite(price) or price <= 0:
                continue
            args = main.get('clickParam', {}).get('args', {})
            free = args.get('tag') == 'freeship'
            cards.append(dict(href=f'https://www.goofish.com/item?id={key}', title=title,
                              price=price, text=title, chips=[], free_shipping=free,
                              image=item.get('picUrl', '')))
        except (KeyError, TypeError, ValueError, AttributeError):
            continue
    return SearchPayload(cards, 'parse_failed' if rows and not cards else '')


class SearchResponses:
    def __init__(self, page, query):
        self.page, self.query = page, query
        self.results, self.tasks = {}, set()
        page.on('response', self.on_response)

    def on_response(self, response):
        url = urlsplit(response.url)
        if not (url.hostname or '').endswith('.goofish.com') or SEARCH_API not in url.path:
            return
        request = response.request
        if request.method != 'POST' or len(self.tasks) >= 6:
            return
        try:
            body = parse_qs(request.post_data or '')
            params = json.loads(body['data'][0])
            if params.get('keyword') != self.query:
                return
            number = int(params['pageNumber'])
            if not 1 <= number <= 3:
                return
        except (KeyError, ValueError, TypeError):
            return
        task = asyncio.create_task(self.capture(response, number))
        self.tasks.add(task)
        task.add_done_callback(self.tasks.discard)

    async def capture(self, response, number):
        try:
            self.results[number] = parse_search_payload(await response.json()) if response.ok else SearchPayload([], 'network')
        except Exception:
            self.results[number] = SearchPayload([], 'parse_failed')

    async def wait(self, number, timeout=2):
        deadline = asyncio.get_running_loop().time() + timeout
        while number not in self.results and asyncio.get_running_loop().time() < deadline:
            await asyncio.sleep(.1)
        return self.results.pop(number, None)

    async def close(self):
        self.page.remove_listener('response', self.on_response)
        pending = list(self.tasks)
        for task in pending:
            task.cancel()
        await asyncio.gather(*pending, return_exceptions=True)
